'use client';

import { useState } from 'react';

import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { filterSummaryOf } from './comparison';
import { ComparisonTable } from './comparison-table';
import { type PlanId, SECTION } from './data';
import { DifferencesSwitch } from './differences-switch';
import { PlanAccordions } from './plan-accordions';

/** On a narrow page the featured plan starts open, so its rows are there when the page is reached. */
const OPEN_AT_START: PlanId[] = ['studio'];

const LOOP_AFTER_MS = 2600;

export default function Pricing06() {
  const [isOnlyDifferences, setIsOnlyDifferences] = useState(false);
  const [openPlans, setOpenPlans] = useState<PlanId[]>(OPEN_AT_START);
  const [announcement, setAnnouncement] = useState('');

  /** Only a person's flip is said: the demonstration flips the same state in silence. */
  function changeOnlyDifferences(isOn: boolean) {
    setIsOnlyDifferences(isOn);
    setAnnouncement(filterSummaryOf(isOn));
  }

  function startOver() {
    setIsOnlyDifferences(false);
    setOpenPlans(OPEN_AT_START);
  }

  const steps: AutoplayStep[] = [
    { after: 2200, run: () => setIsOnlyDifferences(true) },
    { after: 1700, run: () => setOpenPlans(['agency']) },
    { after: 2600, run: () => setIsOnlyDifferences(false) },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: startOver,
  });

  useKeptHeight(ref);

  return (
    <section className='@container'>
      <div
        ref={ref}
        className='mx-auto flex max-w-5xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24'
      >
        <div className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.description}
          </p>
        </div>
        <div className='hidden @3xl:block'>
          <ComparisonTable
            isOnlyDifferences={isOnlyDifferences}
            onOnlyDifferencesChange={changeOnlyDifferences}
          />
        </div>
        <div className='flex flex-col gap-4 @3xl:hidden'>
          <DifferencesSwitch
            isOn={isOnlyDifferences}
            onChange={changeOnlyDifferences}
            className='bg-foreground/[0.04] rounded-xl px-4 py-3'
          />
          <PlanAccordions
            isOnlyDifferences={isOnlyDifferences}
            openPlans={openPlans}
            onOpenPlansChange={setOpenPlans}
          />
        </div>
        <p className='text-muted-foreground text-xs'>{SECTION.footnote}</p>
      </div>
      <LiveRegion message={announcement} />
    </section>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  fadePresence,
  rowPresenceOf,
} from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { CellMark } from './cell-mark';
import {
  actionVariantOf,
  formatPrice,
  type RowPresence,
  visibleRowsOf,
} from './comparison';
import { type Group, GROUPS, type Plan, PLANS, type Row } from './data';
import { DifferencesSwitch } from './differences-switch';

const ROW_FADE = fadePresence();

/** The featured plan keeps one quiet band of tint from its header to its last row. */
const FEATURED_BAND = 'bg-primary/[0.03] dark:bg-primary/[0.05]';

/**
 * The line under the header is drawn by each cell, so it stays with the header while it sticks.
 * The one-pixel height lets the content fill the cell, so the featured band reaches its top.
 */
const HEAD_CELL =
  'bg-background sticky top-0 z-10 h-px p-0 text-left align-bottom font-normal shadow-[inset_0_calc(var(--hairline)*-1)_0_var(--border)]';

function bandOf(plan: Plan) {
  if (plan.isFeatured) {
    return FEATURED_BAND;
  }
  return undefined;
}

function PlanHead({ plan }: { plan: Plan }) {
  const price = formatPrice(plan.price);

  return (
    <th scope='col' className={HEAD_CELL}>
      <div
        className={cn(
          'relative isolate flex h-full flex-col gap-3 rounded-t-xl p-4',
          bandOf(plan)
        )}
      >
        {plan.isFeatured && <Wash />}
        <span className='text-sm font-medium'>{plan.name}</span>
        <span className='flex flex-wrap items-baseline gap-x-1.5'>
          <span className='text-2xl font-semibold tabular-nums'>{price}</span>
          <span className='text-muted-foreground text-xs'>
            {plan.priceNote}
          </span>
        </span>
        <Button
          size='sm'
          variant={actionVariantOf(plan)}
          nativeButton={false}
          render={<a href='#' />}
          className='self-start'
        >
          {plan.action}
        </Button>
      </div>
    </th>
  );
}

type GroupHeadProps = {
  group: Group;
  presence: RowPresence;
};

function GroupHead({ group, presence }: GroupHeadProps) {
  return (
    <motion.tr {...ROW_FADE}>
      <th scope='rowgroup' className='p-0 text-left font-medium'>
        <motion.div {...presence} className='overflow-hidden'>
          <div className='pt-7 pb-2 text-sm'>{group.title}</div>
        </motion.div>
      </th>
      {PLANS.map((plan) => (
        <td key={plan.id} className={cn('p-0', bandOf(plan))} />
      ))}
    </motion.tr>
  );
}

type FeatureRowProps = {
  row: Row;
  presence: RowPresence;
};

/** Every cell folds its own height, so the row closes from its tallest cell down to nothing. */
function FeatureRow({ row, presence }: FeatureRowProps) {
  return (
    <motion.tr {...ROW_FADE} className='hairline-b border-border'>
      <th scope='row' className='p-0 text-left font-normal'>
        <motion.div {...presence} className='overflow-hidden'>
          <div className='py-3 pe-4 text-pretty'>{row.feature}</div>
        </motion.div>
      </th>
      {PLANS.map((plan) => (
        <td key={plan.id} className={cn('p-0', bandOf(plan))}>
          <motion.div {...presence} className='overflow-hidden'>
            <div className='px-4 py-3'>
              <CellMark cell={row.cells[plan.id]} />
            </div>
          </motion.div>
        </td>
      ))}
    </motion.tr>
  );
}

type ComparisonTableProps = {
  isOnlyDifferences: boolean;
  onOnlyDifferencesChange: (isOn: boolean) => void;
};

/** The plans side by side under a header that sticks, with the rows every plan shares folding away on demand. */
export function ComparisonTable({
  isOnlyDifferences,
  onOnlyDifferencesChange,
}: ComparisonTableProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);

  return (
    <table className='w-full table-fixed text-[13px]'>
      <caption className='sr-only'>
        The plans of Larchwork compared feature by feature
      </caption>
      <colgroup>
        <col className='w-[34%]' />
        {PLANS.map((plan) => (
          <col key={plan.id} />
        ))}
      </colgroup>
      <thead>
        <tr>
          <th scope='col' className={HEAD_CELL}>
            <div className='flex h-full flex-col justify-end gap-3 py-4 pe-4'>
              <span className='text-sm font-medium'>Features</span>
              <DifferencesSwitch
                isOn={isOnlyDifferences}
                onChange={onOnlyDifferencesChange}
              />
            </div>
          </th>
          {PLANS.map((plan) => (
            <PlanHead key={plan.id} plan={plan} />
          ))}
        </tr>
      </thead>
      {GROUPS.map((group) => {
        const rows = visibleRowsOf(group, isOnlyDifferences);
        const hasRows = rows.length > 0;
        return (
          <tbody key={group.id}>
            <AnimatePresence initial={false}>
              {hasRows && (
                <GroupHead key='title' group={group} presence={presence} />
              )}
              {rows.map((row) => (
                <FeatureRow key={row.id} row={row} presence={presence} />
              ))}
            </AnimatePresence>
          </tbody>
        );
      })}
    </table>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import {
  Accordion,
  AccordionItem,
  AccordionPanel,
  AccordionTrigger,
} from '@/registry/ndeko/ui/accordion';
import { Button } from '@/registry/ndeko/ui/button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { CellMark } from './cell-mark';
import {
  actionVariantOf,
  formatPrice,
  type RowPresence,
  visibleRowsOf,
} from './comparison';
import { type Group, GROUPS, type Plan, type PlanId, PLANS } from './data';

function isPlanId(value: unknown): value is PlanId {
  return PLANS.some((plan) => plan.id === value);
}

type PlanGroupProps = {
  group: Group;
  plan: Plan;
  isOnlyDifferences: boolean;
  presence: RowPresence;
};

function PlanGroup({
  group,
  plan,
  isOnlyDifferences,
  presence,
}: PlanGroupProps) {
  const rows = visibleRowsOf(group, isOnlyDifferences);
  const hasRows = rows.length > 0;

  return (
    <>
      <AnimatePresence initial={false}>
        {hasRows && (
          <motion.h4
            key='title'
            {...presence}
            className='text-foreground overflow-hidden text-[13px] font-medium'
          >
            <span className='block pt-3 pb-1'>{group.title}</span>
          </motion.h4>
        )}
      </AnimatePresence>
      <ul className='text-foreground flex flex-col'>
        <AnimatePresence initial={false}>
          {rows.map((row) => (
            <motion.li key={row.id} {...presence} className='overflow-hidden'>
              <div className='flex items-center justify-between gap-3 py-1.5'>
                <span className='min-w-0 text-pretty'>{row.feature}</span>
                <span className='shrink-0 text-end'>
                  <CellMark cell={row.cells[plan.id]} />
                </span>
              </div>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </>
  );
}

type PlanAccordionsProps = {
  isOnlyDifferences: boolean;
  openPlans: PlanId[];
  onOpenPlansChange: (openPlans: PlanId[]) => void;
};

/** On a narrow page each plan opens on its own, with the same rows folding away on demand. */
export function PlanAccordions({
  isOnlyDifferences,
  openPlans,
  onOpenPlansChange,
}: PlanAccordionsProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);

  function changeOpenPlans(value: unknown[]) {
    const ids = value.filter(isPlanId);
    onOpenPlansChange(ids);
  }

  return (
    <Accordion
      value={openPlans}
      onValueChange={changeOpenPlans}
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      {PLANS.map((plan) => {
        const price = formatPrice(plan.price);
        return (
          <AccordionItem
            key={plan.id}
            value={plan.id}
            className='relative isolate px-4'
          >
            {plan.isFeatured && <Wash />}
            <AccordionTrigger className='py-4'>
              <span className='flex min-w-0 flex-col gap-0.5'>
                <span className='text-sm'>{plan.name}</span>
                <span className='text-muted-foreground text-xs font-normal tabular-nums'>
                  {price} {plan.priceNote}
                </span>
              </span>
            </AccordionTrigger>
            <AccordionPanel className='pb-4 text-[13px]'>
              {GROUPS.map((group) => (
                <PlanGroup
                  key={group.id}
                  group={group}
                  plan={plan}
                  isOnlyDifferences={isOnlyDifferences}
                  presence={presence}
                />
              ))}
              <Button
                size='sm'
                variant={actionVariantOf(plan)}
                nativeButton={false}
                render={<a href='#' />}
                className='mt-4'
              >
                {plan.action}
              </Button>
            </AccordionPanel>
          </AccordionItem>
        );
      })}
    </Accordion>
  );
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Switch } from '@/registry/ndeko/ui/switch';

import { filterSummaryOf } from './comparison';

type DifferencesSwitchProps = {
  isOn: boolean;
  onChange: (isOn: boolean) => void;
  className?: string;
};

/** The Only differences switch, with a line that says what it hides. */
export function DifferencesSwitch({
  isOn,
  onChange,
  className,
}: DifferencesSwitchProps) {
  const summary = filterSummaryOf(isOn);

  return (
    <div className={cn('flex flex-col gap-1.5', className)}>
      <label className='flex w-fit cursor-pointer items-center gap-2.5 text-[13px] font-medium'>
        <Switch checked={isOn} onCheckedChange={onChange} />
        Only differences
      </label>
      <p className='text-muted-foreground text-xs text-pretty'>
        <Swap swapKey={summary}>{summary}</Swap>
      </p>
    </div>
  );
}

import { CheckIcon, MinusIcon } from '@/registry/ndeko/lib/icons';

import type { Cell } from './data';

/** A check for included, a dash for not included, or the value itself; a screen reader hears the words. */
export function CellMark({ cell }: { cell: Cell }) {
  if (cell.kind === 'check') {
    return (
      <span className='inline-flex'>
        <CheckIcon className='size-4' />
        <span className='sr-only'>Included</span>
      </span>
    );
  }
  if (cell.kind === 'dash') {
    return (
      <span className='text-muted-foreground inline-flex'>
        <MinusIcon className='size-4' />
        <span className='sr-only'>Not included</span>
      </span>
    );
  }
  return <span className='tabular-nums'>{cell.text}</span>;
}

import type { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { countOf, nounOf } from '@/registry/ndeko/lib/words';

import {
  type Cell,
  type Group,
  GROUPS,
  type Plan,
  PLANS,
  type Row,
} from './data';

/** How a row of either view comes and goes: its height and its opacity. */
export type RowPresence = ReturnType<typeof rowPresenceOf>;

const PRICE_FORMATTER = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});

export function formatPrice(amount: number) {
  return PRICE_FORMATTER.format(amount);
}

/** The featured plan carries the one primary action of the block. */
export function actionVariantOf(plan: Plan) {
  if (plan.isFeatured) {
    return 'default' as const;
  }
  return 'outline' as const;
}

/** A check and a dash compare by kind, a value by its text. */
function signatureOf(cell: Cell) {
  if (cell.kind === 'value') {
    return cell.text;
  }
  return cell.kind;
}

function isSameInEveryPlan(row: Row) {
  const cells = PLANS.map((plan) => row.cells[plan.id]);
  const signatures = cells.map(signatureOf);
  const [first] = signatures;
  return signatures.every((signature) => signature === first);
}

function isDifferent(row: Row) {
  return !isSameInEveryPlan(row);
}

/** With Only differences on, a row every plan shares folds away; a group left with no row folds its title too. */
export function visibleRowsOf(group: Group, isOnlyDifferences: boolean) {
  if (!isOnlyDifferences) {
    return group.rows;
  }
  return group.rows.filter(isDifferent);
}

function countSharedRows() {
  let count = 0;
  for (const group of GROUPS) {
    const shared = group.rows.filter(isSameInEveryPlan);
    count += shared.length;
  }
  return count;
}

function countRows() {
  let count = 0;
  for (const group of GROUPS) {
    count += group.rows.length;
  }
  return count;
}

const ROW_COUNT = countRows();

const SHARED_ROW_COUNT = countSharedRows();

function hiddenSummaryOf(count: number) {
  const rows = countOf(count, 'row');
  const verb = nounOf(count, 'is', 'are');
  return `${rows} every plan shares ${verb} hidden`;
}

/** The line under the switch, and what a screen reader hears when a person flips it. */
export function filterSummaryOf(isOnlyDifferences: boolean) {
  if (isOnlyDifferences) {
    return hiddenSummaryOf(SHARED_ROW_COUNT);
  }
  return `All ${ROW_COUNT} features shown`;
}

export type PlanId = 'solo' | 'studio' | 'agency';

export type Plan = {
  id: PlanId;
  name: string;
  price: number;
  priceNote: string;
  action: string;
  isFeatured: boolean;
};

export type Cell =
  { kind: 'check' } | { kind: 'dash' } | { kind: 'value'; text: string };

export type Row = {
  id: string;
  feature: string;
  cells: Record<PlanId, Cell>;
};

export type Group = {
  id: string;
  title: string;
  rows: Row[];
};

const YES: Cell = { kind: 'check' };

const NO: Cell = { kind: 'dash' };

function valueOf(text: string): Cell {
  return { kind: 'value', text };
}

